'use strict';
// Content alignment and detailed review of the four supplied PDFs. Page mappings are
// internal review metadata; the learning UI contains no citation/link inputs.
window.PDFContent=(()=>{
 const lessons={};
 const add=(id,pages,lead,steps,request,result)=>{lessons[id]={pages,lead,steps,request,result};};
 add('1-0','1','생성형 AI는 기업 분석을 돕는 도구입니다.',[
  ['답변을 정답으로 받아들이지 않기','AI는 학습한 정보를 바탕으로 답변을 생성하므로 존재하지 않는 정보를 사실처럼 말하는 할루시네이션이나 수치 해석 오류가 생길 수 있습니다. 자료를 직접 전달했더라도 검토가 필요합니다.'],
  ['분석 전에 공통 기준 정하기','불확실하면 알 수 없다고 말하기, 확실한 정보와 추측 구분하기, 질문이 모호하면 추가 질문하기, 확인되지 않은 사실을 단정하지 않기를 요청합니다.'],
  ['내가 직접 확인하고 사용하기','기업의 공식 발표와 최근 정보를 비교해 잘못되거나 빠진 내용을 고칩니다. 프롬프트만 입력했다고 정확성이 보장되지는 않습니다.']
 ],'기업 분석을 도와줄 때 불확실한 정보는 알 수 없다고 말해 줘. 확인한 사실과 추측을 구분하고, 질문이나 자료가 부족하면 먼저 물어봐. 확인되지 않은 사실은 단정하지 마.','확인한 기업 정보와 아직 알 수 없는 내용을 나눕니다. AI가 제시한 사업·실적·계획은 직접 확인한 뒤 자기소개서와 면접 준비에 사용합니다.');
 add('1-1','2','기업 분석 작업에 맞춰 Gemini·Claude·Perplexity를 활용하세요.',[
  ['Gemini · 기업 소식과 산업 동향','기업에 대한 최근 뉴스와 산업 동향을 조사할 때 활용합니다. 조사할 기업과 필요한 주제를 구체적으로 알려줍니다.'],
  ['Claude · 긴 문서의 이해와 분석','사업보고서와 IR 자료처럼 분량이 많은 글을 전달하고 핵심 내용과 시사점을 정리할 때 활용합니다.'],
  ['Perplexity · 검색 기반 정보 확인','검색형 AI를 활용해 기업 정보를 조사하고 답변이 실제 기업 정보와 맞는지 직접 확인합니다. 서비스별 이용 가능한 기능은 사용 화면에서 확인하세요.']
 ],'지원 기업의 주력 사업과 최근 산업 동향을 정리해 줘. 사업보고서를 전달하면 기업 개요·주력 수익 구조·향후 사업 방향으로 나눠 요약해 줘.','최신 소식 조사와 긴 문서 분석은 서로 다른 작업입니다. 필요한 작업을 먼저 정한 뒤 그 작업에 맞는 도구를 선택합니다.');
 add('1-2','3–5','고정할 나의 정보와 작업마다 바꿀 지침을 나누세요.',[
  ['나의 정보 · 재사용할 프로필','학력·교육, 기술·어학 자격, Main·Sub 기술을 정리합니다. 주요 프로젝트 2~3개가 있다면 이름과 담당, 핵심 기술, 트러블슈팅, 결과로 나눕니다.'],
  ['해결하고자 하는 문제','현재 상황, 구체적으로 필요한 도움, 제약 조건을 적습니다. 기업 분석·직무 분석·자기소개서 작성 등 작업에 따라 내용을 바꿉니다.'],
  ['출력 방법','결과 형식, 구성 순서, 분량, 언어 스타일을 지정합니다. 개요·완성 문단·비교표 중 필요한 형태를 고릅니다.'],
  ['마무리','원하는 어조와 금지 사항을 정합니다. 없는 경력·기술·수치를 만들지 않도록 하고 회사명·직무명·기술명을 확인하도록 요청합니다.']
 ],'#나의 정보\n학력·교육, 자격, Main·Sub 기술, 프로젝트별 담당·핵심 기술·문제 해결·결과\n\n#해결하고자 하는 문제\n지원 기업의 사업과 직무를 분석하고 내 경험과 연결하고 싶어.\n\n#출력 방법\n기업의 주요 사업 → 직무 요구 → 내 경험과의 연결 순서로 정리해 줘.\n\n#마무리\n제공하지 않은 경력·기술·수치는 만들지 말고 부족한 내용은 질문해 줘.','프로필은 재사용하고 현재 상황·요청·출력 방식·마무리 조건을 바꿉니다. 원문은 산책 기록 서비스의 인증 API, 버킷리스트 앱의 캐싱, 스터디 관리 서비스의 배포 자동화를 프로젝트별로 구분합니다.');
 add('1-3','6–9','사업·실적·연구개발을 조사하고 기업의 방향을 파악하세요.',[
  ['DART · 사업보고서 읽기','정기공시에서 사업보고서나 분기보고서를 찾습니다. ‘Ⅱ. 사업의 내용’의 주요 제품 및 서비스, 주요 계약 및 연구개발 활동, 기타 참고사항을 살펴봅니다.'],
  ['DartPoint AI · 공시 분석','기업명이나 종목 코드로 기업을 검색하고 공시 분석 화면을 확인합니다. AI 어시스턴트를 사용할 수 있다면 기업의 전략·리스크·기회 요인을 질문하고 보고서 내용과 비교합니다.'],
  ['한경컨센서스 · 증권사 리포트','검색 기간을 최근 1년 등으로 정하고 기업을 검색합니다. 리포트의 요약을 읽어 제품·서비스 현황과 향후 전망을 정리합니다. 전망과 이미 달성한 실적을 구분하세요.'],
  ['비상장기업 · 기업 소개와 투자 정보','혁신의숲·TheVC는 스타트업 투자 정보, 원티드는 기업·직무별 채용 정보를 살펴볼 때 활용합니다. 스타트업얼라이언스·넥스트유니콘·삼성전자 C-Lab, 예비 유니콘 지원 정보, 스타트업 위클리도 조사 목적에 맞춰 활용합니다.']
 ],'사업보고서에서 주요 제품·서비스와 연구개발 활동을 정리하고, 증권사 리포트의 요약에서 현재 사업과 앞으로의 전망을 구분해 줘.','주요 제품·서비스 / 매출 구성 / 연구개발과 기술 방향 / 향후 전망으로 정리합니다. 문서의 위치나 주소를 적는 대신 취업 준비에 활용할 핵심 내용을 기록합니다.');
 add('1-4','10–12','수집한 정보를 다섯 영역으로 요약하고 필요한 질문을 이어가세요.',[
  ['기업 개요 및 실적','기업을 한 줄로 요약하고 주력 수익 구조와 최근 매출·영업이익 흐름을 정리합니다.'],
  ['시장 분석','산업 내 위치, 주요 경쟁사, 차별점과 경쟁 우위 요소를 정리합니다.'],
  ['사업 동향과 기업 문화','주력 사업의 성과, 미래 신사업·R&D 방향을 정리합니다. 일하는 방식·인재상·복지 제도도 함께 살펴봅니다.'],
  ['종합 SWOT와 추가 질문','강점·약점·기회·위협을 정리합니다. 산업 내 위치, 집중 사업, 경쟁사와의 차이, 근무 환경 중 더 궁금한 내용을 추가로 질문합니다.']
 ],'제공한 사업보고서와 리포트를 바탕으로 기업 개요 및 실적, 시장 분석, 사업 동향, 기업 문화, 종합 SWOT 순서로 분석해 줘. 수치·사업명·기술 키워드와 불릿 위주로 정리하고 확인하지 못한 내용은 만들지 마.','현대오토에버 사례는 기업 개요와 수익 구조를 살펴본 뒤 종합 SWOT로 이어갑니다. 자기소개서에 쓸 경쟁 우위와 입사 후 포부에 연결할 기술 방향을 골라 추가 분석합니다.');
 add('1-5','13','AI가 정리한 기업 정보의 오류와 빠진 내용을 확인하세요.',[
  ['검토할 정보 고르기','앞 단계의 분석에서 자기소개서나 면접에 사용할 사업·실적·기술·계획을 고릅니다.'],
  ['공식 홈페이지와 최근 기사 대조','기업이 공개한 정보와 최근 기사를 확인해 답변이 맞는지, 중요한 내용이 빠지지 않았는지 살펴봅니다.'],
  ['확인한 내용으로 수정','잘못된 정보는 고치고, 확인하지 못한 내용은 미확인으로 남깁니다. 확인할 수 없다는 이유만으로 거짓이라고 단정하지 않습니다.']
 ],'[기업명]의 공식 홈페이지와 최근 기사를 확인해 앞서 분석한 정보가 맞는지, 빠진 내용은 없는지 검토해 줘. 확인하기 어려운 내용은 확인할 수 없다고 구분해 줘.','사업 추진 계획을 출시 완료로 적었거나 실적 단위를 잘못 적은 경우를 찾아 수정합니다. 확인하지 못한 정보는 지원 문서에 단정적으로 쓰지 않습니다.');
 add('1-6','14','공고의 담당 업무·필요 자격·우대 사항·사용 기술을 확인하세요.',[
  ['지원 공고 읽기','기업 채용 홈페이지나 채용 공고에서 지원 직무의 담당 업무, 필요 역량, 자격, 우대 사항, 사용 기술을 파악합니다.'],
  ['정보가 부족할 때 보완하기','경쟁사의 동일 직무 공고 또는 지원 기업의 경력직 공고를 참고해 업무를 이해합니다. 참고 공고의 조건을 지원 공고의 필수 자격으로 바꾸지 않습니다.'],
  ['직무 분석에 쓸 내용 정리','업무·자격·우대·기술을 나눠 정리하고 모르는 점을 적습니다. 다음 단계에서 강조할 역량을 분석합니다.']
 ],'이 채용 공고의 담당 업무, 필수 자격, 우대 사항, 사용 기술을 나눠 정리해 줘. 설명이 부족한 부분은 같은 직무나 경력직 공고를 참고하되 지원 공고와 구분해 줘.','원문은 LG CNS와 채용 플랫폼의 공고를 살펴보는 흐름을 보여줍니다. 공고를 복사하거나 업무 내용을 정리한 뒤 직무 분석으로 이어갑니다.');
 add('1-7','15–16','공고 특징 → 강점 키워드 → 필요 경험 유형으로 직무를 분석하세요.',[
  ['공고 특징','공고에서 특히 강조하는 업무, 특이한 문구와 조건을 정리합니다. 유사 공고와 비교했다면 어떤 차이가 있는지 살펴봅니다.'],
  ['강점 키워드 1~2개','공고의 업무에서 필요한 역량을 도출하고 기업이 강조하는 핵심 키워드와 연결 이유를 적습니다.'],
  ['필요 경험 유형과 내 경험 연결','역량을 보여줄 수 있는 경험 유형을 구체화합니다. 나의 정보를 함께 제공했다면 가장 연관성 높은 경험을 연결합니다.']
 ],'공고의 업무와 자격 요건을 바탕으로 공고 특징, 강점 키워드 1~2개, 필요한 경험 유형을 분석해 줘. 내 경험 중 연관성이 높은 것을 연결하고 공고에 없는 내용은 추측하지 마.','LG CNS Robotics Engineer 사례는 로봇 자체 제어보다 시스템 통합·연동, 현장 배포와 운영 안정화에 주목합니다. 시스템 연동·예외 처리와 통합 배포·성능 최적화가 키워드로 이어집니다.');
 add('1-8','17–18','직무가 요구하는 역량과 나의 경험을 비교해 강점·약점을 찾으세요.',[
  ['나의 정보 제공','희망 직무·산업, 학력·교육·자격·기술과 주요 프로젝트 경험을 구체적으로 정리합니다.'],
  ['필요 역량과 매칭','앞서 도출한 핵심 역량·강점 키워드와 내 경험을 비교합니다. 역할·행동·결과를 중심으로 연결점을 찾습니다.'],
  ['강점과 약점 정리','직무에 활용할 수 있는 강점, 부족한 역량, 보완할 경험을 정합니다. AI의 적합도 의견은 준비 방향을 정하는 참고로 활용합니다.']
 ],'분석한 직무의 핵심 역량과 나의 교육·기술·프로젝트 경험을 비교해 줘. 역량별로 연결할 경험, 나의 강점과 약점, 추가로 준비할 내용을 정리해 줘.','원문 사례는 외부 API 재시도·입력 검증 경험을 시스템 연동·예외 처리와, Docker·Jenkins 경험을 통합 배포·자동화와 연결합니다. 같은 기술 이름보다 실제 수행한 역할을 설명합니다.');
 add('1-9','19','기업 분석 결과를 지원 동기와 입사 후 포부에 연결하세요.',[
  ['지원 동기 소재 찾기','기업의 경쟁 우위·강점과 내가 중요하게 생각하는 기업 선택 기준·가치관의 연결점을 찾습니다.'],
  ['입사 후 포부 구체화','기업의 단기 기술 목표와 중장기 개발 방향을 살펴봅니다. 단기·중장기 목표로 나누고 기여할 점과 더 배울 점을 적습니다.'],
  ['교정·교열과 문장 다변화','AI 초안을 그대로 제출하지 않습니다. 맞춤법·문법·어색한 표현을 고치고 도입부와 문장 구조를 다양하게 바꿔 내 언어로 완성합니다.']
 ],'기업의 강점과 내 선택 기준을 연결해 지원 동기 소재를 정리해 줘. 입사 후 포부는 단기·중장기로 나누고 내가 기여할 점과 더 배울 점을 포함해 줘. 마지막에는 반복되는 도입부와 어색한 문장을 점검해 줘.','기업을 왜 선택했는지 → 어떤 경험을 갖고 있는지 → 어떤 방향으로 기여할지 연결합니다. 글을 작성한 뒤 내 생각과 표현으로 다시 다듬는 시간을 확보합니다.');
 add('2-0','2–4','문항이 묻는 의도와 필요한 역량·경험을 먼저 파악하세요.',[
  ['문항과 직무 배경 전달','기업·직무, 자기소개서 문항, 담당 업무·필요 역량·우대 사항과 나의 정보를 함께 제공합니다.'],
  ['네 항목으로 문항 분석','질문 의도, 핵심 역량, 추천 경험 및 어필 포인트, 추가적으로 알면 좋은 점으로 나눠 분석합니다.'],
  ['작성할 경험과 방향 결정','추천받은 경험이 실제 이력과 맞는지 살펴봅니다. 문항에 반드시 답해야 할 내용과 강조할 기술·행동을 정합니다.']
 ],'문항을 질문 의도 / 핵심 역량 / 추천 경험 및 어필 포인트 / 추가적으로 알면 좋은 점으로 분석해 줘. 기업·직무와 나의 정보를 함께 고려하고 추상적인 조언보다 구체적인 작성 방향을 제안해 줘.','현대오토에버 차량전장SW 사례에서는 지원 이유·커리어 계획 문항과 역량을 키운 노력·경험 문항을 나눠 봅니다. 관심 계기·직무 역량·성장 방향 중 각 문항에 필요한 요소를 정합니다.');
 add('2-1','5–9','직무와 가장 연관된 대표 경험 하나를 깊이 있게 설명하세요.',[
  ['연관 경험 2~3개 비교','실제 경험에서 지원 직무와 관련된 후보를 고르고 기술, 역할, 행동, 결과와 직무 연관성을 비교합니다.'],
  ['대표 경험 하나 선택','최종 추천 소재, 추천 이유, 스토리텔링 포인트를 정합니다. 여러 경험을 얕게 나열하기보다 선택한 경험을 구체화합니다.'],
  ['핵심 키워드 추가 탐색','선택한 경험의 핵심 역량·강점, 강조할 성과, 직무 기여 연결점을 추가 질문합니다. 성과 수치는 실제 측정값이 있을 때 사용합니다.']
 ],'문항과 지원 직무에 맞는 경험 2~3개를 비교하고 대표 경험 하나를 추천해 줘. 추천 이유와 스토리텔링 포인트를 정리한 뒤, 그 경험의 핵심 역량 키워드와 직무 기여 연결점을 제안해 줘.','올리브영 소프트웨어 엔지니어 사례는 Redis 캐싱을 통한 조회 부하 개선 경험을 대표 소재로 골라 캐싱 전략·지연 시간·데이터 정합성으로 키워드를 확장합니다. 예시 수치를 내 성과로 옮기지 않습니다.');
 add('2-2','10–12','STAR·KPI·FAB를 문항의 목적에 맞게 사용하세요.',[
  ['STAR · 경험의 흐름','Situation은 상황, Task는 내 역할과 과제, Action은 직접 한 행동, Result는 결과입니다. 문제 해결·목표 달성·협업 경험을 논리적으로 정리합니다.'],
  ['KPI · 결과를 수치로','목표 달성을 측정하는 핵심 성과 지표입니다. 속도·정확도·시간·사용자 수 등 목표와 결과를 비교해 무엇이 달라졌는지 설명합니다.'],
  ['FAB · 강점과 기업의 가치 연결','Feature는 나의 특징·경험, Advantage는 그 경험의 장점, Benefit은 기업·조직에 기여할 가치입니다. 직무 강점·지원 동기·입사 후 포부에 활용합니다.']
 ],'이 경험을 STAR의 상황·과제·행동·결과로 정리하고, 측정한 성과가 있다면 KPI로 제시해 줘. 내 강점이 기업에 어떤 가치로 이어지는지는 FAB로 설명해 줘.','STAR는 경험의 구조, KPI는 성과를 보여줄 지표, FAB는 강점과 기여의 연결입니다. 세 개를 같은 종류의 문단 양식으로 취급하지 않고 필요한 요소를 조합합니다.');
 add('2-3','13–16','지원 계기 → 역량을 키운 노력 → 입사 후 기여로 구성하세요.',[
  ['FAB로 연결점 정하기','관심을 갖게 된 계기, 실제 기술·프로젝트 경험, 그 역량이 기업에 주는 가치를 연결합니다.'],
  ['소제목과 두괄식 문단 작성','소제목 → 지원 동기 → 관련 역량·경험 → 입사 후 목표·기여 방안 순서로 씁니다. 실제 문항의 분량을 지킵니다.'],
  ['기업·직무에 맞게 보완','어느 회사에나 적용되는 일반론을 줄이고 기업의 사업·직무와 내 경험의 연결을 구체화합니다.'],
  ['자가 점검','기업 고유성, 역량을 키운 구체적 행동, 실행 가능한 계획, 계기와 포부의 반복, 산업·직무 연결을 확인합니다.']
 ],'FAB를 활용해 소제목 / 지원 동기 / 관련 역량과 경험 / 입사 후 목표와 기여 방안 순서로 작성해 줘. 기업·직무에 맞는 실제 경험을 두괄식으로 쓰고 제공하지 않은 사실은 추가하지 마.','현대글로비스 IT Infra Management 사례는 시스템 전반의 구조에 대한 관심을 캐싱·배포 자동화 경험과 연결하고 입사 후 인프라 운영 기여로 마무리합니다. 회사 소개를 길게 쓰기보다 나의 계기와 행동을 드러냅니다.');
 add('2-4','17–19','대표 문제 하나를 STAR로 풀어 나만의 해결 방식을 보여주세요.',[
  ['대표 사례와 핵심 문장','직무와 가장 관련된 프로젝트 하나를 고르고 소제목과 핵심 요약으로 시작합니다.'],
  ['상황과 내 과제','문제가 발생한 배경, 영향, 내가 맡은 역할과 반드시 해결해야 했던 과제를 설명합니다.'],
  ['원인 분석과 실행','가설·재현·검증 과정, 해결 방법을 선택한 이유, 직접 실행한 행동을 구체적으로 씁니다.'],
  ['결과·배움과 자가 점검','결과와 배운 점을 정리하고 직무 기여로 연결합니다. 나만의 방법론, 원인 추적, 도구 선택 이유, 측정 기준, 대표 사례 집중 여부를 확인합니다.']
 ],'대표 프로젝트 하나를 소제목 / 핵심 요약 / 상황 / 내 과제 / 원인 분석과 행동 / 결과·배움 / 직무 기여 순서로 작성해 줘. STAR를 사용하고 내가 선택한 방법의 이유를 드러내 줘.','신협 IT개발·관리 사례는 조회 부하와 응답 지연 문제를 캐싱으로 개선하는 과정을 보여줍니다. TTL 설정만으로 정합성이 보장된다고 쓰지 않고, 실제 적용·검증한 범위와 한계를 설명합니다.');
 add('2-5','20–23','높은 목표를 세운 이유와 단계별 달성 전략을 보여주세요.',[
  ['목표와 설정 이유','대표 경험 하나를 선택하고 시작 상태, 스스로 정한 목표, 그 목표가 필요했던 이유를 적습니다.'],
  ['단계별 전략과 실행','목표별 해결 전략을 구분합니다. 전략 수립 → 실행 → 중간 확인과 조정 순서로 직접 한 행동을 씁니다.'],
  ['성과와 인사이트','목표와 최종 결과를 비교하고 그 과정에서 얻은 배움을 지원 직무와 연결합니다.'],
  ['자가 점검','목표·달성값의 대조, 단계별 전략, 핵심 성과의 가독성, 수치 일관성, 직무에서의 재현 가능성을 확인합니다.']
 ],'KPI를 활용해 소제목 / 목표와 설정 이유 / 단계별 달성 전략 / 최종 성과와 인사이트 순서로 작성해 줘. 목표별로 어떤 행동을 했는지 구분하고 수치는 실제 기록만 사용해 줘.','한국고용정보원 정보화 사례는 인증 예외율과 응답 시간이라는 두 목표를 나눕니다. 재시도 로직은 일시 실패 대응, 입력 검증은 잘못된 요청 차단을 위한 행동으로 각각 설명합니다.');
 add('2-6','24–26','상대의 우려·내 판단 기준·구체적 조율 행동을 설명하세요.',[
  ['공동 목표와 난관','의견 대립·역할 혼선·진행 차질이 무엇이었는지 적고 상대가 우려한 이유도 설명합니다.'],
  ['판단 기준과 설득','문제를 풀기 위해 제시한 합리적 기준과 비교 내용을 적습니다. 직접 제안·설명·조율한 행동을 드러냅니다.'],
  ['성과와 배움','합의가 실행된 결과와 협업에서 배운 점을 정리합니다. 단순 역할 분담이나 친하게 지냈다는 설명에서 그치지 않습니다.'],
  ['자가 점검','갈등 원인, 주도적 판단 기준, 설득 방식, 협업 후 변화, 직무와의 연결을 확인합니다.']
 ],'STAR를 활용해 소제목 / 협업 상황과 난관 / 판단 기준과 조율 행동 / 성과와 배움 순서로 작성해 줘. 상대의 우려와 내가 실제로 설득·조정한 행동을 구체적으로 보여줘.','금융결제원 전산직 사례는 빠른 수동 구현과 지속 가능한 자동화 사이의 이견을 다룹니다. 반복 작업·오류 가능성과 운영 안정성을 기준으로 자동화 방안을 제안하고 실행한 과정을 설명합니다.');
 add('2-7','27–29','기존 방식의 한계를 새롭게 정의하고 직접 검증한 시도를 보여주세요.',[
  ['기존 한계와 문제 인식','관행적인 방식이 어떤 비효율을 만들었는지 구체적으로 설명합니다.'],
  ['새 접근과 차별성','기존과 무엇을 다르게 보았는지, 어떤 대안을 생각했고 왜 선택했는지 적습니다.'],
  ['주도적 실행과 검증','아이디어를 실제로 적용한 과정, 시험·피드백·수정 내용을 씁니다. 도구를 사용했다는 사실만 나열하지 않습니다.'],
  ['성과·배움·적용 가능성','개선 전후 결과와 배운 점을 정리합니다. 기존 한계, 판단·검증, 성과, 입사 후 적용 가능성을 점검합니다.']
 ],'소제목 / 기존 방식의 한계 / 새 해결 전략과 차별성 / 구체적 실행 / 성과와 인사이트 순서로 작성해 줘. 문제를 새롭게 정의한 이유와 직접 검증한 부분을 강조해 줘.','LIG D&A SW 사례는 모든 코드를 같은 비중으로 리뷰하던 방식을 AI 요약·위험도 분류로 개선합니다. 평균 리뷰 시간 30분→24분은 20% 감소한 학습 사례이며 실제 경험과 구분합니다.');
 add('2-8','30–33','직무 연결·가독성·핵심 강점을 중심으로 초안을 다듬으세요.',[
  ['직무 연관성 강화','직무와 관련이 약한 표현을 줄이고 요구 역량과 연결되는 실제 기술·경험을 강조합니다.'],
  ['문장 가독성 개선','주어·서술어 호응을 바로잡고 복잡한 문장을 나눕니다. 꼭 필요한 기술 개념은 유지하며 읽기 쉬운 말로 바꿉니다.'],
  ['핵심 강점과 내 표현','경험 나열을 줄이고 전략·기술적 시도를 드러냅니다. 추상적 문장을 구체적 경험으로 바꾸고, 모호한 표현을 줄이며 실제 느낀 점·성장 포인트를 담습니다.'],
  ['피드백과 수정본 검토','주요 수정 포인트를 요약하고 분량에 맞는 수정본을 만듭니다. 기존 사실을 바꾸거나 새로운 경험·수치를 덧붙이지 않습니다.']
 ],'초안을 직무 연관성, 문장 가독성, 핵심 강점, 구체적인 내 표현의 기준으로 검토해 줘. 개선 피드백 3가지 내외와 수정본을 제시하고 원래 사실관계와 분량 제한을 지켜 줘.','현대글로비스 사례는 회사 일반론을 줄이고 직무 연결을 강화하며 어려운 용어를 정돈합니다. 첨삭 과정에서 새로 제안된 측정값·기술은 실제 기록으로 확인하기 전 채택하지 않습니다.');
 add('2-9','34–36','내용과 형식을 나눠 최종 글을 점검하세요.',[
  ['내용 점검 5가지','기업·직무 맞춤, 명확한 지원 동기, 구체적인 경험·사례, 구조와 논리 흐름, 차별화된 강점을 확인합니다.'],
  ['형식 점검 5가지','문단과 구성, 명확하고 간결한 문장, 맞춤법·문법·어색한 표현, 읽기 쉬운 길이와 표현, 지원자 자신의 개성을 확인합니다.'],
  ['수정 후 다시 읽기','보완이 필요한 항목과 이유를 정리해 고친 뒤 문항 요구·사실·글자 수를 재확인합니다. 외부 표절·AI 검사 실습은 기존 보류 범위를 유지합니다.']
 ],'완성된 글을 내용 5가지와 형식 5가지 체크리스트로 점검해 줘. 항목별 충족 여부와 보완 이유를 적고 사실관계·문항·분량을 유지한 수정 방향을 제안해 줘.','첫 문장이 핵심 강점과 맞는지, 주장과 경험이 이어지는지, 반복 표현이 없는지 확인합니다. 최종 문장은 직접 소리 내어 읽고 제출 조건에 맞춰 마무리합니다.');
 add('3-0','2','지원 직무의 핵심 역량을 최대 3개로 정리하고 경험을 매칭하세요.',[
  ['공고와 직무 정보 확인','담당 업무·필수 역량·기술을 읽고 직무가 무엇을 요구하는지 정리합니다.'],
  ['중요도에 따른 우선순위','필요한 기술과 역량을 최대 3개로 정리하고 우선순위의 이유를 적습니다.'],
  ['나의 정보와 연결','실제로 보유한 기술과 프로젝트만 사용해 연관성이 높은 순서로 매칭합니다. 포트폴리오에서 먼저 보여줄 경험을 정합니다.']
 ],'지원 직무의 핵심 기술과 필요 역량을 중요도 순으로 3개까지 정리하고, 나의 정보에 실제 포함된 기술·프로젝트 중 연관성이 높은 것을 순서대로 연결해 줘.','핵심 역량 → 관련 기술 → 직접 수행한 프로젝트 → 보여줄 내용을 연결합니다. 지원 직무에 필요한 역량이 프로필과 프로젝트 구성에 일관되게 드러나도록 합니다.');
 add('3-1','3–8','기술·문제 해결 성과·가치관의 세 방향으로 한 줄을 만드세요.',[
  ['기술과 경험으로 시작','프로필 최상단에 넣을 문구입니다. 추상적인 수식어보다 주요 기술과 실제 문제 해결 경험을 사용합니다.'],
  ['세 방향 후보와 추천 이유','기술 스택 중심, 문제 해결·성과 중심, 가치관 중심으로 30~50자 내외의 문장과 추천 이유를 만듭니다.'],
  ['역량 키워드로 보완','역량사전의 행동 기준을 참고해 실제 경험에 맞는 표현을 찾습니다. 키워드만 바꾸지 말고 그 행동을 설명할 수 있는지 확인합니다.'],
  ['직무에 맞춰 가변 지침 수정','기업·직무에 맞게 해결할 문제·출력 방법·마무리를 바꾸고 실제 기술명과 경험이 정확한지 검토합니다.']
 ],'내 기술과 프로젝트를 바탕으로 기술 스택 중심 / 문제 해결·성과 중심 / 가치관 중심의 캐치프레이즈 3개와 추천 이유를 제안해 줘. 문장당 30~50자 내외로 쓰고 없는 성과는 추가하지 마.','신한은행 뱅킹서비스 개발·운영 사례는 캐싱과 배포 자동화 경험을 서비스 안정성·운영 효율과 연결합니다. “열정적인 개발자” 같은 일반적 수식어 대신 실제 역량이 드러나도록 다듬습니다.');
 add('3-2','9–10','Main·Sub 기술과 실제 사용 수준을 함께 보여주세요.',[
  ['기술 선별과 분류','직무와 연관된 기술을 중심으로 Main·Sub를 구분하고 프로젝트에서 어떻게 사용했는지 적습니다.'],
  ['5단계 숙련도 기준','기초: 튜토리얼 가능 / 초급: 예제 참고 구현 / 중급: 문서를 보며 독립 개발 / 고급: 프로젝트에서 주도적 활용 / 전문가: 코드 리뷰·멘토링으로 구분합니다.'],
  ['중요도와 숙련도 시각화','직무 중요도는 별 등으로, 숙련도는 막대 등으로 표시하고 판단 이유를 함께 씁니다. 판단할 경험이 부족하면 미확인으로 남깁니다.']
 ],'프로젝트에서 실제 사용한 기술을 Main·Sub로 나누고 5단계 숙련도와 이유를 정리해 줘. 직무 중요도는 별, 숙련도는 막대로 구분한 표로 보여주고 판단하기 어려운 기술은 미확인으로 표시해 줘.','Java·Spring Boot·Redis·Docker 등 기술마다 담당한 구현과 사용 범위를 적습니다. 중요도와 숙련도는 다른 기준이므로 별 개수를 곧바로 실력 점수로 해석하지 않습니다.');
 add('3-3','11–12·14','프로젝트 개요와 내 역할·기여를 핵심 위주로 설명하세요.',[
  ['직무 연관성에 따라 정렬','지원 직무와의 연관성과 프로젝트 완성도를 고려해 보여줄 순서를 정합니다.'],
  ['배경·목표·주요 기능','프로젝트의 배경과 목표, 주요 구현 기능을 소개합니다.'],
  ['내 역할과 기여','팀 안에서 담당한 파트와 직접 기여한 내용을 구체화합니다. 기여율을 제시할 때는 설명할 수 있는 기준을 사용하고 모호하면 협업 과정과 역할을 보여줍니다.']
 ],'프로젝트를 지원 직무와 연관성이 높은 순서대로 정렬하고, 각 프로젝트의 개요와 담당 역할·기여를 핵심 위주로 2~3줄씩 정리해 줘.','신한은행 뱅킹서비스 사례는 캐싱을 다룬 버킷리스트 앱, 인증·실시간 통신을 다룬 산책 서비스, 배포 자동화를 다룬 스터디 서비스를 직무와 연결해 소개합니다.');
 add('3-4','12·14','사용 기술의 선택 이유와 실제 구현을 연결하세요.',[
  ['사용한 핵심 기술 명시','프로젝트에서 실제 사용한 기술과 담당한 기능을 적습니다.'],
  ['선택 이유와 대안 비교','요구 사항을 만족하기 위해 왜 그 기술을 선택했는지, 검토한 대안과 비교했을 때 어떤 장점·한계가 있었는지 설명합니다.'],
  ['구현 사항 구체화','주요 기능과 데이터 흐름, 직접 구현한 범위를 직무와 연결해 설명합니다. 기술 이름만 나열하지 않습니다.']
 ],'프로젝트의 핵심 기술을 선택한 이유와 검토한 대안 대비 장점·한계를 정리해 줘. 담당 기능이 어떤 흐름으로 동작하는지 구체화하고 지원 직무와 연결해 줘.','자주 읽고 변경이 적은 데이터를 캐싱한 이유, 배포 과정에 Docker·Jenkins를 적용한 이유처럼 요구 사항과 기술 선택이 이어지게 씁니다. 실제로 검토하지 않은 대안은 검토했다고 말하지 않습니다.');
 add('3-5','12–14','STAR와 개선 전→개선 후→변화율로 해결 사례를 정리하세요.',[
  ['STAR로 트러블슈팅 정리','문제 상황, 내 과제, 원인 분석과 기술적 행동, 결과를 순서대로 설명합니다.'],
  ['성과 수치화','같은 조건에서 측정한 개선 전·후 값과 변화율을 제시합니다. 측정하지 않은 값은 만들어 넣지 않습니다.'],
  ['시각화 방식 선택','핵심 수치는 빅 넘버 카드, 전후 비교는 차트, 시스템과 기술 선택은 아키텍처 구조도로 표현합니다.']
 ],'대표 트러블슈팅을 STAR로 정리해 줘. 성과는 개선 전 → 개선 후 → 변화율의 3단 구조로 쓰고 빅 넘버 카드·비교 차트·아키텍처 중 알맞은 시각화 방식도 추천해 줘.','원문의 캐싱 사례에서 800ms→240ms는 응답 시간 70% 감소입니다. 전후 비교에는 단위와 같은 측정 조건을 함께 표시합니다. 내 측정값이 없으면 구조 변화와 확인한 결과를 설명합니다.');
 add('3-6','13–14','KPT로 경험의 성찰과 다음 개선 방향을 보여주세요.',[
  ['Keep · 유지할 점','잘한 행동, 새로 배운 기술, 다음에도 유지할 문제 해결 방식을 정리합니다.'],
  ['Problem · 아쉬운 점','프로젝트에서 부족했던 점과 원인, 개선이 필요한 부분을 구체적으로 적습니다.'],
  ['Try · 다음 시도','앞선 아쉬움을 바탕으로 다음에 시도할 개선·고도화 방향과 학습 계획을 정합니다.']
 ],'프로젝트의 잘한 점과 배운 점은 Keep, 아쉬운 점은 Problem, 향후 개선 방향은 Try로 나눠 KPT 회고 문단을 작성해 줘.','캐싱 사례는 구조적으로 부하를 줄인 경험을 Keep으로, 정합성과 캐시 만료 시 요청 집중을 충분히 고려하지 못한 점을 Problem으로, 동기화·만료 전략을 실험할 계획을 Try로 정리합니다.');
 add('3-7','15','직무·활용 목적·기업 문화에 맞는 포트폴리오 양식을 고르세요.',[
  ['PPT','대기업·공공기관·SI 기업을 예로 소개합니다. 다이어그램과 화면을 배치하고 발표 순서를 조정하기 좋지만 세부 기술 설명과 디자인·업데이트에 부담이 있습니다.'],
  ['Notion','스타트업·IT 플랫폼·프리랜서·에이전시를 예로 소개합니다. 프로젝트 수정과 구조화가 쉽지만 오프라인 사용과 일부 환경의 접근에 제약이 있습니다.'],
  ['개인 웹사이트','테크 스타트업·디자인·크리에이티브 분야를 예로 소개합니다. 개성과 구현 역량을 보여줄 수 있지만 제작·유지 관리에 시간과 비용이 듭니다.'],
  ['영상','게임 개발사·프리랜서·미디어·콘텐츠 분야를 예로 소개합니다. 데모와 설명 방식을 보여주기 좋지만 촬영·편집 부담과 기업별 선호 차이가 있습니다.']
 ],'지원 직무와 제출 조건을 고려해 PPT·Notion·개인 웹사이트·영상의 장단점을 비교하고 적합한 양식을 추천해 줘.','기업 유형은 양식 활용의 예시입니다. 실제 지원처의 제출 조건을 먼저 확인하고, 보여줄 내용·제작 시간·관리 부담을 고려해 주 양식을 선택합니다.');
 add('3-8','16–19','먼저 장별 원고를 만들고 Canva에서 생성·편집하세요.',[
  ['10장 구성의 초안 만들기','지원 직무에 맞춰 장별 제목과 핵심 내용을 정리합니다. 커버의 캐치프레이즈·핵심 역량 3줄, 기술 스택, 프로젝트별 개요·역할·STAR·성과, 회고·성장 방향을 배치합니다.'],
  ['장별 시각화 지정','아키텍처·전후 비교 차트·빅 넘버 카드처럼 내용을 잘 설명할 시각 요소를 제안받습니다.'],
  ['Canva에서 제작','포트폴리오 템플릿을 선택하고 AI 편집에서 나의 정보와 원고·요청문을 전달합니다. 프레젠테이션 개요와 슬라이드를 생성합니다.'],
  ['내려받아 직접 수정','PPT 또는 PDF로 내려받고 내용·레이아웃·글자 크기·잘림을 확인합니다. AI 초안을 그대로 제출하지 않습니다.']
 ],'지원 직무에 맞는 10장 포트폴리오 초안을 작성해 줘. 장별 제목·핵심 내용·추천 시각화를 제시하고, 커버에는 캐치프레이즈와 핵심 역량 3줄, 프로젝트에는 역할·STAR·전후 성과를 포함해 줘.','원문의 10장 예시는 커버 → 목차·역량 → 기술 스택 → 프로젝트 3개의 개요와 해결 사례 → 회고·성장 방향·연락 정보입니다. 실제 프로젝트 수와 제출 분량에 맞춰 조정합니다.');
 add('3-9','20–21','프로필·기술·프로젝트·KPT를 Notion 블록으로 구성하세요.',[
  ['상단 프로필','캐치프레이즈, 인적 사항, 핵심 역량 3줄을 배치하고 콜아웃으로 강조합니다.'],
  ['기술 스택과 자격','Main·Sub 기술, 자격과 교육 사항을 표와 목록으로 정리합니다.'],
  ['프로젝트 상세와 회고','개요·담당 역할·STAR·개선 전후 성과를 배치하고 긴 설명은 토글로 나눕니다. KPT 회고로 성장 방향을 보여줍니다.'],
  ['웹 화면과 PDF 확인','원고를 옮긴 뒤 콜아웃·토글·표를 직접 정돈합니다. 웹에서 읽기 쉬운지, PDF에서 내용이 잘리거나 빠지지 않는지 확인합니다.']
 ],'Notion 포트폴리오를 상단 프로필 / 기술 스택과 자격 / 프로젝트 상세 / KPT 회고 순서로 작성해 줘. 콜아웃·표·토글을 배치할 위치를 제안하고 웹과 PDF에서 읽기 쉽게 정리해 줘.','원문은 백엔드 개발자의 기술·프로젝트를 프로필과 표로 보여준 뒤 프로젝트별 STAR와 전후 성과, 공통 KPT로 연결합니다. 붙여넣은 뒤 실제 블록과 PDF 출력 형태를 확인합니다.');
 add('4-0','1–4','공고와 내 프로젝트로 CS·기술 3개, 프로젝트 질문 3개를 준비하세요.',[
  ['공고와 나의 정보 전달','기업·직무, 담당 업무·자격·우대·기술과 실제 프로젝트 경험을 함께 제공합니다.'],
  ['질문·의도·선정 이유','CS·기술 질문 TOP 3와 프로젝트 경험 질문 TOP 3를 나누고 각 질문의 출제 의도와 선정 이유를 정리합니다.'],
  ['꼬리 질문으로 확장','왜 그 기술인지 → 다른 대안은 무엇인지 → 규모가 커지면 어떻게 할지 → 장애 시 어떻게 복구할지의 흐름으로 준비합니다.']
 ],'공고와 나의 정보를 바탕으로 CS·기술 질문 3개와 프로젝트 경험 질문 3개를 선별해 줘. 질문별 출제 의도와 선정 이유를 한 줄씩 적고 실제 경험을 검증할 꼬리 질문도 제안해 줘.','LG CNS AX/DX Engineer 사례는 Redis 캐시 정합성, Spring 요청 처리·병목, 외부 API 타임아웃·재시도와 함께 캐싱 선택 이유·인증 예외 처리·여러 서버의 스케줄 중복 실행을 질문합니다.');
 add('4-1','5–9','질문 유형에 맞는 구조로 40초~1분 답변을 만드세요.',[
  ['CS 질문 · 3단 구성','핵심 개념을 2~3문장으로 설명 → 실제 프로젝트 경험 또는 일반 예시 → 지원 직무와의 연결 순서로 답합니다.'],
  ['프로젝트 질문 · 4단 구성','프로젝트 개요·담당 역할 → 기술 선택 이유와 Trade-off → 문제 해결·주요 성과 → 회고·성장 포인트 순서로 답합니다.'],
  ['말하기와 후속 질문 준비','자연스러운 구어체로 40초~1분 내외로 정리합니다. 내가 하지 않은 경험과 측정하지 않은 수치는 추가하지 않고 후속 질문에 설명할 판단 기준을 준비합니다.']
 ],'질문 하나를 골라 40초~1분의 구어체 답변을 작성해 줘. CS는 개념→경험·예시→직무 연결, 프로젝트는 개요·역할→선택 이유→해결·성과→회고 순서로 구성해 줘.','캐시 질문에서는 개념과 정합성 고려 사항을 먼저 설명하고 실제 프로젝트 적용과 직무 연결로 마무리합니다. 프로젝트 질문에서는 Redis를 썼다는 사실보다 반복 조회를 줄이려 한 이유를 설명합니다.');
 add('4-2','10–12','다섯 기준으로 직무 답변을 평가하고 부족한 부분을 고치세요.',[
  ['다섯 평가 기준','문제 해결 과정, 질문에 대한 핵심 메시지, 기술·경험의 직무 연결, 협업과 내 역할 구분, 자연스럽고 간결한 말하기를 확인합니다.'],
  ['충분·보완 필요와 이유','기준마다 답변의 어떤 부분이 충분하고 무엇이 빠졌는지 적습니다. 확인할 수 없는 내용은 추가 질문합니다.'],
  ['실제 경험으로 보완','나의 정보 안에서 역할·판단·행동을 구체화하고 40초~1분 구어체로 다듬습니다. 없던 분석 과정이나 수치를 만들어 넣지 않습니다.']
 ],'이 답변을 문제 해결 과정 / 핵심 메시지 / 직무 연결 / 협업과 내 역할 / 자연스럽고 간결한 표현의 5가지 기준으로 충분 또는 보완 필요로 평가해 줘. 이유와 수정본을 제시하고 없는 경험·수치는 추가하지 마.','원문 사례는 캐싱 적용과 결과는 드러나지만 병목 판단과 본인의 역할이 부족한 답변을 보완합니다. 실제 로그 분석 기록이 없으면 했다고 추가하지 않고 당시 확인한 구조와 판단을 설명합니다.');
 add('4-3','13–16','임원 면접 질문을 네 관점에서 준비하세요.',[
  ['기업·업계 분석','사업 방향, 최근 이슈, 산업 변화와 지원 동기를 연결한 질문을 준비합니다.'],
  ['직무 경험','프로젝트·협업·도전·성장 경험에서 판단 기준, 주인의식, 성장 가능성을 확인할 질문을 만듭니다.'],
  ['조직 적합성과 태도','기업의 가치와 조직 문화를 바탕으로 협업·커뮤니케이션·갈등 대응·적응 방식을 묻는 질문을 만듭니다.'],
  ['자기소개서·이력서 맞춤','제출 서류와 나의 정보에 있는 경험·가치관·강점·약점을 구체적으로 확인할 질문, 출제 의도, 꼬리 질문을 정리합니다.']
 ],'나의 정보와 자기소개서를 바탕으로 임원 면접 예상 질문 10개를 작성해 줘. 기업·업계, 직무 경험, 조직 적합성과 태도, 제출 서류의 네 관점을 활용하고 질문마다 의도와 꼬리 질문 1개를 붙여 줘.','KB국민은행 IT 사례는 캐싱 경험을 금융 데이터의 정확성·안정성 관점으로 확장하고, 일정과 안정성의 충돌·실수 보고·협업 태도·장기 성장 기준을 질문합니다.');
 add('4-4','17–18','경험 하나로 나의 역할·판단 기준·행동·배움을 설명하세요.',[
  ['경험 선택','질문 의도와 꼬리 질문을 고려해 실제 협업·도전·프로젝트 경험 중 적합한 사례 하나를 고릅니다.'],
  ['핵심 메시지와 답변 구성','나의 역할 → 판단 기준과 행동 → 결과와 배운 점 → 기업·직무 연결 순서로 핵심을 먼저 말합니다.'],
  ['꼬리 질문의 일관성','40초~1분의 자연스러운 구어체로 다듬고 후속 질문에도 같은 판단 기준을 적용할 수 있는지 확인합니다.']
 ],'이 질문의 의도와 꼬리 질문을 고려해 실제 경험 하나를 고르고 선택 이유를 설명해 줘. 역할→판단 기준·행동→결과·배움→직무 연결 순서로 40초~1분 답변을 작성해 줘.','금융 서비스에 캐싱을 적용할 수 있느냐는 질문에는 프로젝트에서의 판단을 설명하고, 금융에서는 원본 데이터의 정확성과 장애 시 안정성을 우선하겠다는 기준으로 이어갑니다.');
 add('4-5','19–21','핵심 메시지·판단·역할·직무 연결·표현을 점검하세요.',[
  ['다섯 기준 평가','질문 의도에 맞는 핵심 메시지, 판단 기준과 행동, 구체적인 경험과 내 역할, 기업·직무 연결, 자연스러운 표현을 확인합니다.'],
  ['부족한 부분과 이유','각 기준을 충분·보완 필요로 나누고 질문 의도와 꼬리 질문을 함께 고려해 보완점을 적습니다.'],
  ['최종 답변과 꼬리 질문','나의 정보 안에서 실제 판단과 역할을 구체화합니다. 40초~1분 답변을 만든 뒤 꼬리 질문에도 기준이 일관되는지 확인합니다.']
 ],'임원 답변을 핵심 메시지 / 판단 기준·행동 / 실제 경험·역할 / 기업·직무 연결 / 자연스러운 표현으로 평가해 줘. 충분·보완 필요와 이유를 적고 꼬리 질문을 고려한 수정 답변을 작성해 줘.','캐싱 답변을 보완할 때 “빠르니까 선택했다”에서 끝내지 않고 데이터 특성과 요구 사항을 함께 판단했다는 점을 설명합니다. 장애·불일치 대응 질문에서도 같은 기준을 유지합니다.');
 add('4-6','22–25','질문 하나씩 음성으로 연습하고 종료 후 종합 평가를 받으세요.',[
  ['준비와 진행 지침','지원 기업·직무, 나의 정보, 질문 방식과 평가 기준을 전달합니다. 개인 맞춤 설정은 선택 사항이며 대화에 지침을 직접 입력해도 됩니다.'],
  ['음성 대화 시작','음성 대화 기능을 선택하고 마이크 권한과 입력 상태를 확인합니다. 음성을 글로 바꾸는 받아쓰기와 질문·답변을 음성으로 주고받는 대화를 구분합니다.'],
  ['2~3개 질문 이어가기','한 번에 질문 하나씩 진행합니다. 답변 직후 평가하지 않고 답변에 따른 다음 질문·꼬리 질문을 이어가도록 요청합니다.'],
  ['종료 후 피드백','핵심 메시지·논리 흐름·경험 구체성·직무 연관성·말하기 자연스러움으로 종합 평가를 받고 텍스트로 확인해 보완합니다.']
 ],'지금부터 지원 기업·직무의 모의 면접을 진행해 줘. 한 번에 질문 하나만 하고 내 답변 직후 평가하지 말고 다음 질문이나 꼬리 질문을 이어가 줘. 총 2~3개 질문이 끝나면 핵심 메시지·논리·경험·직무 연결·말하기를 종합 평가해 텍스트로 정리해 줘.','원문은 캐시 적용 → 데이터 불일치 대응 → 성능과 정확성의 우선순위로 질문을 이어갑니다. 음성 인식 결과를 읽어 기술 용어 오류를 고치고 반복되는 표현과 부족한 경험 설명을 보완합니다.');
 add('4-7','26–29','준비한 질문으로 영상 답변을 녹화하고 전달 습관을 점검하세요.',[
  ['면접 연습과 질문 선택','뷰인터에서 연습 유형을 선택합니다. ‘내가 만든 질문’에 지원 기업·직무와 관련해 준비한 질문을 넣어 연습합니다.'],
  ['카메라·마이크와 영상 답변','권한을 허용하고 화면·음성 입력을 확인합니다. 카메라를 보며 답변하고 시선·표정·속도·전달 방식을 직접 살펴봅니다.'],
  ['리포트와 세부 분석','종합 리포트, 세부 분석, AI 면접위원 평가를 확인하고 제공되는 경우 PDF로 보관합니다. 영상에서 실제 관찰한 습관과 수정할 답변을 구분합니다.'],
  ['사람과도 연습하기','AI 피드백을 반영해 다시 답하고 취업 컨설턴트 등 실제 사람과 대면 연습을 이어갑니다.']
 ],'준비한 질문에 카메라를 보며 답하고, 녹화 영상과 리포트에서 답변 내용·시선·속도·전달 습관을 점검한다. 수정할 답변과 다음 연습에서 바꿀 행동을 정리한다.','원문은 종합 리포트·세부 분석·면접위원 평가 화면을 보여줍니다. 성격이나 합격 가능성 수치를 사실로 단정하지 않고 실제 답변과 관찰 가능한 전달 습관을 연습에 활용합니다.');
 add('4-8','30–36','설정 → 자기소개 → 메인·꼬리 질문 → 피드백 → 재연습으로 진행하세요.',[
  ['모의 면접 설정','싸피엔스에서 모의 면접·새 면접 시작을 선택합니다. 금융·삼성·일반 기업 등 목적에 맞는 유형, 기업·직무, 자기소개서 또는 채용공고 내용을 입력합니다.'],
  ['자기소개와 메인 면접','자기소개 후 메인 질문과 답변에 따른 꼬리 질문을 진행합니다. 텍스트 또는 음성으로 답하고 음성 인식 결과를 확인합니다.'],
  ['질문별 피드백으로 보완','부족하다고 평가된 항목과 다음에 볼 점을 확인합니다. 질문과 실제 경험을 AI에 전달해 답변 구조를 보완하고 부족한 기술 개념은 따로 학습합니다.'],
  ['종합 리포트와 반복 연습','직무 적합도·강점·보완점과 다음 준비 방향을 확인합니다. 반복해서 부족한 부분을 정리하고 다음 모의 면접에 반영합니다.']
 ],'나온 면접 질문과 부족하다고 평가된 항목, 다음에 볼 점을 바탕으로 답변을 보완해 줘. 실제 적용한 내용과 아직 공부할 내용을 구분하고, 나의 역할·판단·행동을 더 구체적으로 설명해 줘.','원문의 예시는 자기소개 뒤 메인 질문 5개와 꼬리 질문, 질문별 피드백·종합 리포트로 이어집니다. 실제 이용 가능 시기와 진행 구성은 계정 안내를 확인하고 리포트의 점수보다 반복되는 보완 과제에 집중합니다.');
 return {lessons};
})();

function renderPDFContentLesson(){
 const id=currentStep.id,lesson=PDFContent.lessons[id];
 if(!lesson||selectedTab==='write')return false;
 const el=document.querySelector('#tab-content');
 const career=window.CareerLessons.lessons[id];
 const samplePrompt=Workbook.isPrompt(id)?Workbook.compose(pdfExampleData(id),id):'';
 if(selectedTab==='guide'){
  el.innerHTML=`<div class="lesson-lead"><h3>${esc(lesson.lead)}</h3></div><ol class="instruction-list">${lesson.steps.map(([title,body])=>`<li><strong>${esc(title)}</strong><p>${esc(body)}</p></li>`).join('')}</ol>${renderPDFOutputSpec(id)}${id==='2-9'?'<p class="tiny">내용 5개·형식 5개와 함께 사실·제출 조건 2개를 추가로 확인합니다.</p>':''}${career?renderCareerSkillReference(career)+renderCareerExtras(career)+renderCareerChecklist(career):''}${id==='1-0'?companyAccuracyGuide():''}<div class="next-action">${lessonButton('작성 예시 살펴보기','example')}${lessonButton('내 내용 작성하기','write')}</div>`;
 }else{
  el.innerHTML=`<div class="gallery-heading"><h3>${esc(lesson.lead)}</h3></div><div class="tip-box">학습용 요청문과 사례입니다. 실제 지원 기업의 현재 정보나 나의 경험으로 단정하지 말고, 내 문항·직무·경험으로 바꿔 사용하세요.</div><section class="example-case"><div class="case-body"><h3>요청은 이렇게 구체화하세요</h3><div class="example-block"><pre>${esc(lesson.request)}</pre></div><button type="button" class="secondary" id="copy-pdf-request">요청문 복사하기</button></div></section><h3>작성칸별 입력 예시</h3><p>아래는 입력 방법을 연습하기 위한 가상 사례입니다. 작성 공간과 같은 항목으로 보여주며 내 기록에 자동 입력하지 않습니다.</p>${renderPDFFieldExamples(id)}${samplePrompt?`<details class="full-prompt"><summary>예시 입력을 연결한 완성 요청문 보기</summary><div class="example-block"><pre>${esc(samplePrompt)}</pre></div><button type="button" class="secondary" id="copy-pdf-example">예시 완성 요청문 복사</button></details>`:''}${renderPDFOutputSpec(id)}<section class="adapt-note"><h3>가이드북 사례와 적용 방법</h3><p>${esc(lesson.result)}</p></section>${career?renderCareerPreparation(career)+renderCareerSkillReference(career,true)+renderCareerExtras(career):''}<div class="next-action">${lessonButton('내 내용 작성하기','write')}</div>`;
 }
 if(selectedTab==='example'){document.querySelector('#copy-pdf-request').onclick=()=>copyText(lesson.request);const button=document.querySelector('#copy-pdf-example');if(button&&samplePrompt)button.onclick=()=>copyText(samplePrompt);}
 if(id==='1-0'&&selectedTab==='guide'){const button=document.querySelector('#copy-company-accuracy');if(button)button.onclick=()=>copyText(CompanyLessons.accuracyPrompt,document.querySelector('#company-accuracy-prompt'));}
 bindLessonButtons();return true;
}

// Retain the storage schema for older records; only obsolete metadata inputs
// are omitted from the visible form and completion requirements.
PDFContent.hidden=(id,key)=>id==='1-3'&&['location','dates'].includes(key)||id==='1-6'&&key==='source';
PDFContent.visibleFields=(id,fields)=>fields.filter(([key])=>!PDFContent.hidden(id,key));
PDFContent.cleanInstruction=text=>String(text||'')
 .replace(/출처·발행일·확인일·근거 위치/g,'')
 .replace(/출처·근거 위치·확인일/g,'')
 .replace(/출처·위치·확인일/g,'')
