function composePDFContent(data,id){
 const lesson=PDFContent.lessons[id];if(!lesson)return '';
 if(id==='1-3')return '';
 const fields=id==='1-5'?Workbook.verificationFields:Workbook.fields(id);
 const career=CareerLessons.lessons[id];
 const keys=career?career.inputs:id==='1-4'?['target','sources']:id==='1-7'?['target','posting','experience','comparison']:fields.map(([key])=>key);
 const blocks=id==='1-5'?Workbook.verificationCards(data).map((card,i)=>{
  const parts=fields.filter(([key])=>['claim','source','comparison'].includes(key)&&typeof card[key]==='string'&&card[key].trim()).map(([key,label])=>`[${label}]\n${card[key]}`);
  return parts.length?`[검토 ${i+1}]\n${parts.join('\n\n')}`:'';
 }).filter(Boolean):keys.flatMap(key=>typeof data[key]==='string'&&data[key].trim()?[`[${fields.find(f=>f[0]===key)?.[1]||key}]\n${data[key]}`]:[]);
 if(!blocks.length)return '';
 return lesson.request+'\n\n[제공한 입력]\n'+blocks.join('\n\n')+'\n\n[출력 방법]\n'+lesson.output.map((text,i)=>`${i+1}. ${text}`).join('\n')+'\n\n[검토 기준]\n'+lesson.checks.map(text=>'- '+text).join('\n')+'\n\n실제 문항·제출 조건·사용자가 지정한 분량과 형식을 예시 기본값보다 우선해 주세요. 제공한 기업·직무 정보와 실제 경험 안에서 작성하고, 없는 경력·기술·수치는 만들지 말고 부족한 내용은 질문해 주세요.';
}

